+    // arrange
+    const accessories = new Map<string, BasementGuardianPlatformAccessory>();
+    const persistedContexts: unknown[] = [];
+    let receivedAt = 1000;
+    let writes = 0;
+    const store = createDeviceStateStore({ clock: { now: () => receivedAt }, log: createSilentLog() });
